import org.lwjgl.system.MemoryStack;
import org.lwjgl.util.lmdb.MDBEnvInfo;
import org.lwjgl.util.lmdb.MDBStat;

class TripleEmergencySizingTest {

	private static final long INITIAL_MAP_BYTES = 8L * 1024L * 1024L;
	private static final double GROWTH_RATIO = 0.01d;
	private static final long LARGE_NAMESPACE_BYTES = 2L * 1024L * 1024L;

	@Test
	@Timeout(value = 30, unit = java.util.concurrent.TimeUnit.SECONDS)
	void emergencyReplaySizesTheCompleteNamespaceTransaction(@TempDir Path dataDirectory) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setTripleDBSize(INITIAL_MAP_BYTES)
				.setMapGrowthThreshold(GROWTH_RATIO)
				.setAutoGrow(true);
		try (EmergencySizingTripleStore tripleStore = new EmergencySizingTripleStore(dataDirectory.toFile(), config)) {
			tripleStore.armMapFullOnNextCommit();
			String namespace = "urn:lmdb:emergency-sizing:" + "n".repeat(Math.toIntExact(LARGE_NAMESPACE_BYTES));
			Map<String, String> expectedNamespaces = Map.of("large", namespace);

			tripleStore.commitNamespaceSnapshot(expectedNamespaces);

			assertTrue(tripleStore.replayValidated(),
					"the retry must size the active replayed transaction from its complete native footprint");
			assertEquals(expectedNamespaces, tripleStore.readNamespaceSnapshot(),
					"the emergency MAP_FULL retry must preserve the complete authoritative namespace snapshot");
		}
	}

	private static final class EmergencySizingTripleStore extends TripleStore {
		private final AtomicBoolean failNextCommit = new AtomicBoolean();
		private volatile boolean replayValidated;

		private EmergencySizingTripleStore(File directory, LmdbStoreConfig config) throws IOException {
			super(directory, config, null);
		}

		private void armMapFullOnNextCommit() {
			failNextCommit.set(true);
		}

		private boolean replayValidated() {
			return replayValidated;
		}

		@Override
		int commitWriteTransaction(long transaction) {
			if (failNextCommit != null && failNextCommit.compareAndSet(true, false)) {
				// Native commit consumes its transaction handle even when returning MDB_MAP_FULL.
				mdb_txn_abort(transaction);
				return MDB_MAP_FULL;
			}
			return super.commitWriteTransaction(transaction);
		}

		@Override
		protected void afterMapGrowthReplay() throws IOException {
			try (MemoryStack stack = stackPush()) {
				MDBEnvInfo info = MDBEnvInfo.malloc(stack);
				assertEquals(MDB_SUCCESS, mdb_env_info(env, info));
				MDBStat stats = MDBStat.malloc(stack);
				assertEquals(MDB_SUCCESS, mdb_env_stat(env, stats));
				long projectedUse = LmdbUtil.getNewSize(stats.ms_psize(), writeTxn, 0L);
				long projectedWithReserve = LmdbUtil.saturatedAdd(projectedUse, LmdbUtil.MIN_FREE_SPACE);
				double permittedUse = info.me_mapsize() * GROWTH_RATIO;
				assertTrue(projectedWithReserve < permittedUse,
						"the replayed namespace snapshot and free-space reserve must remain strictly below "
								+ "the actual native map's fullness watermark: projected=" + projectedWithReserve
								+ ", permitted=" + permittedUse + ", map=" + info.me_mapsize());
				replayValidated = true;
			}
			super.afterMapGrowthReplay();
		}
	}
}
